import { ReactNode } from 'react';

export type CardProps = {
  header: ReactNode;
  body: ReactNode;
  footer?: ReactNode;
};

export function Card({ header, body, footer }: CardProps) {
  return (
    <article>
      <header>{header}</header>
      <div data-slot="body">{body}</div>
      {footer ? <footer>{footer}</footer> : null}
    </article>
  );
}
